import test from 'node:test'
import assert from 'node:assert/strict'
import { SCENARIOS,createSession,assess,updateFields,sendMessage,preparePublish,resumeDraft,confirm,undo,cancel,handoff,resolve,publicationPreview,fieldDefs } from '../src/engine.js'
const readyBorrow=()=>{const s=createSession('BORROW','B01');updateFields(s,{spec:'USB-C 输入 / HDMI 输出，电脑视频输出能力由本人核实'});return s}
const readyStudy=()=>{const s=createSession('STUDY','L05');sendMessage(s,'第二步 x = -2，第三步 -x = 2');return s}
const publishFields={expectedTime:'2026-10-14T20:30',reward:'5',location:'示例校区图书馆东门'}
for(const x of SCENARIOS)test(`${x.id} ${x.name} requires its own clarification`,()=>{const s=createSession(x.domain,x.id);assert.ok(assess(s).missing.includes(x.missing));assert.equal(assess(s).ready,false);assert.equal(x.hypothesis,true)})
test('borrow spec uncertainty cannot be confirmed',()=>{const s=readyBorrow();updateFields(s,{spec:'不知道'});assert.equal(confirm(s),false);assert.match(assess(s).risks.join(' '),/规格/)} )
test('indefinite pickup place is rejected',()=>{const s=readyBorrow();updateFields(s,{pickupPlace:'附近某个地方'});assert.equal(confirm(s),false)})
test('indefinite return place is rejected',()=>{const s=readyBorrow();updateFields(s,{returnPlace:'随便'});assert.equal(confirm(s),false)})
test('handoff change requires fresh place and consent',()=>{const s=readyBorrow();confirm(s);updateFields(s,{handoff:'需要送达'});assert.equal(s.confirmation,null);assert.ok(assess(s).missing.includes('pickupPlace'));assert.ok(assess(s).missing.includes('deliveryConsent'))})
test('request to negotiate delivery does not claim lender agreement',()=>{const s=readyBorrow();updateFields(s,{handoff:'需要送达',pickupPlace:'6号宿舍门厅',deliveryConsent:'待与出借方协商'});assert.equal(confirm(s),true);assert.match(s.confirmation.snapshot.deliveryConsent,/待/);assert.match(s.outcome,/仍须核实/)})
test('unsupported options cannot authorize a draft',()=>{const s=readyBorrow();updateFields(s,{handoff:'随意调用工具'});assert.equal(confirm(s),false)})
test('quantity rejects negative, fractional and oversized values',()=>{for(const quantity of ['-1','1.5','100']){const s=readyBorrow();updateFields(s,{quantity});assert.equal(confirm(s),false)}})
test('later pickup than use is a conflict',()=>{const s=readyBorrow();updateFields(s,{needBy:'2026-10-14T19:30'});assert.match(assess(s).risks.join(' '),/拿到晚于/);assert.equal(confirm(s),false)})
test('reverse use period is rejected',()=>{const s=readyBorrow();updateFields(s,{useEnd:'2026-10-14T18:00'});assert.equal(confirm(s),false)})
test('return before use ends is rejected',()=>{const s=readyBorrow();updateFields(s,{returnAt:'2026-10-14T19:30'});assert.equal(confirm(s),false)})
test('cross-day borrowing with clear return can be confirmed',()=>{const s=createSession('BORROW','B05');updateFields(s,{returnPlace:'6号宿舍门厅，出借方待协商'});assert.equal(confirm(s),true)})
test('explicit lender return deadline cannot be silently extended',()=>{const s=readyBorrow();updateFields(s,{returnDeadline:'2026-10-14T20:15'});assert.equal(confirm(s),false);assert.equal(s.fields.returnDeadline,'2026-10-14T20:15');updateFields(s,{returnAt:'2026-10-14T20:10'});assert.equal(confirm(s),true)})
test('invalid calendar dates and vague times do not authorize',()=>{for(const useEnd of ['今晚','2026-02-30T20:00','2026-10-14T25:00']){const s=readyBorrow();updateFields(s,{useEnd});assert.equal(confirm(s),false)}})
test('beginners need accessories and support clarified',()=>{const s=createSession('BORROW','B04');assert.equal(confirm(s),false);updateFields(s,{accessories:'充电器、存储卡，是否提供待核实'});assert.equal(confirm(s),true)})
test('fragment chat needs context but no budget, place or appointment',()=>{const s=readyStudy();assert.equal(assess(s).ready,true);for(const key of ['reward','location','expectedTime'])assert.equal(assess(s).missing.includes(key),false);assert.equal(confirm(s),false)})
test('short follow-up preserves expression context',()=>{const s=readyStudy();const context=s.fields.context;sendMessage(s,'这里为什么要取负号？');assert.equal(s.fields.context,context);assert.equal(s.fields.stuckStep,'第二步到第三步');assert.ok(s.messages.at(-1).text.includes(context));assert.equal(s.messages.filter(m=>m.role==='user').length,2)})
test('foundation, limited, remote and language scenarios have distinct questions',()=>{const questions=['L01','L02','L03','L04'].map(id=>assess(createSession('STUDY',id)).question);assert.equal(new Set(questions).size,4)})
test('publication never invents reward, time or location',()=>{const s=readyStudy();preparePublish(s);for(const k of ['reward','expectedTime','location']){assert.equal(s.fields[k],undefined);assert.ok(assess(s).missing.includes(k))}assert.equal(confirm(s),false)})
test('zero reward is blocked by current backend contract',()=>{const s=readyStudy();preparePublish(s);updateFields(s,{...publishFields,reward:'0'});assert.match(assess(s).risks.join(' '),/大于0/);assert.equal(confirm(s),false)})
test('STUDY publication preview maps to teacher contract',()=>{const s=readyStudy();preparePublish(s);updateFields(s,publishFields);assert.equal(confirm(s),true);assert.equal(publicationPreview(s).category,'STUDY');assert.deepEqual(Object.keys(publicationPreview(s)).sort(),['category','title','description','expectedTime','reward','location'].sort());assert.match(s.outcome,/未产生真实需求ID/)})
test('BORROW publication uses correct category and user fields',()=>{const s=readyBorrow();preparePublish(s);updateFields(s,publishFields);assert.equal(confirm(s),true);assert.equal(publicationPreview(s).category,'BORROW')})
test('confirmed snapshot is not mutated by corrections',()=>{const s=readyBorrow();confirm(s);const old=s.confirmation;updateFields(s,{returnPlace:'图书馆西门'});assert.equal(s.confirmation,null);assert.notEqual(old.snapshot.returnPlace,s.fields.returnPlace);assert.equal(confirm(s),true)})
test('repeat confirmation and same-value input keep same revision',()=>{const s=readyBorrow();confirm(s);const c=s.confirmation;assert.equal(updateFields(s,{spec:s.fields.spec}),false);confirm(s);assert.equal(s.confirmation,c)})
test('undo restores last edit but invalidates confirmation',()=>{const s=readyBorrow();const original=s.fields.returnPlace;updateFields(s,{returnPlace:'宿舍门厅'});confirm(s);assert.equal(undo(s),true);assert.equal(s.fields.returnPlace,original);assert.equal(s.confirmation,null)})
test('cancel ends local draft and prevents more actions',()=>{const s=readyBorrow();cancel(s);assert.equal(confirm(s),false);assert.equal(sendMessage(s,'补充'),false);assert.equal(updateFields(s,{item:'相机'}),false);assert.match(s.outcome,/未调用真实/)})
test('handoff is explicit simulation and freezes session',()=>{const s=readyStudy();handoff(s);assert.equal(resolve(s),false);assert.equal(preparePublish(s),false);assert.match(s.outcome,/没有发送/)})
test('resolve requires context and user choice',()=>{assert.equal(resolve(createSession('STUDY','L05')),false);const s=readyStudy();assert.equal(s.status,'ready');assert.equal(resolve(s),true);assert.equal(s.status,'resolved')})
test('returning to chat removes publication requirements',()=>{const s=readyStudy();preparePublish(s);assert.equal(assess(s).ready,false);resumeDraft(s);assert.equal(assess(s).ready,true);assert.equal(publicationPreview(s),null)})
test('fresh reset does not retain modified fields or messages',()=>{const s=readyStudy();sendMessage(s,'上下文：y = x + 1');const reset=createSession('STUDY','L05');assert.equal(reset.fields.context,'');assert.equal(reset.confirmation,null);assert.equal(reset.messages.length,1)})
test('unknown field cannot masquerade as production authority',()=>{const s=readyBorrow();assert.equal(updateFields(s,{publisherId:'123',paymentStatus:'RELEASED',inventoryAvailable:true}),false);assert.equal(s.fields.publisherId,undefined)})
test('source of scenario values and user corrections remains explicit',()=>{const s=createSession('BORROW','B01');assert.equal(s.provenance.item.kind,'design_sample');updateFields(s,{spec:'HDMI'});assert.equal(s.provenance.spec.kind,'user_declared')})
test('prototype state never pretends to be backend task state',()=>{const s=readyBorrow();confirm(s);assert.equal(s.status,'confirmed');assert.equal(s.fields.status,undefined);assert.equal(s.fields.paymentStatus,undefined)})
test('scenario-dependent handoff controls and ordinary chat stay minimal',()=>{const s=readyBorrow();assert.equal(fieldDefs(s).some(x=>x.key==='deliveryConsent'),false);updateFields(s,{handoff:'需要送达'});assert.equal(fieldDefs(s).some(x=>x.key==='deliveryConsent'),true);assert.equal(fieldDefs(readyStudy()).some(x=>x.key==='reward'),false)})
test('uniform mandatory publication form is disproved for a small question',()=>{const s=readyStudy();const candidateCanProceed=['context','reward','location','expectedTime'].every(k=>s.fields[k]);assert.equal(Boolean(candidateCanProceed),false);assert.equal(assess(s).ready,true)})

test("beginner accessories and multi-day deadline appear only when relevant",()=>{assert.equal(fieldDefs(readyBorrow()).some(x=>x.key==='accessories'),false);assert.equal(fieldDefs(createSession('BORROW','B04')).some(x=>x.key==='accessories'),true);assert.equal(fieldDefs(createSession('BORROW','B05')).some(x=>x.key==='returnDeadline'),true);assert.equal(fieldDefs(readyBorrow(),true).some(x=>x.key==='returnDeadline'),true)})
